// 栈解法
int longestValidParentheses(string s) {
    stack<int> st;
    st.push(-1); // 基准索引
    int ans = 0;
    for (int i = 0; i < s.size(); i++) {
        if (s[i] == '(') {
            st.push(i);
        } else {
            st.pop();
            if (st.empty()) {
                st.push(i); // 新基准
            } else {
                ans = max(ans, i - st.top());
            }
        }
    }
    return ans;
}
// 栈存索引不是字符 | 初始-1基准 | 栈空重新设基准 | i-st.top()得长度
